// The inline render path must render a snippet written in a component's tag, and import what it calls.
//
// A component given a template by its parent depends on two things in the same place.
//
// 1. `generateInlineNodes`'s `walk` needs a case for the node: without one, a `default: break;` would
//    drop it from the emitted module, silently. The alpha scoped slot (`<slot name="item" let:label>`)
//    once went that way; its beta form, `@snippet item(option) { … }` (#489, #492), is held here.
//
// 2. The module imports what it calls. The alpha slot's function was generated by the template path,
//    and a module that called `html` without importing it threw `ReferenceError: html is not
//    defined`. A snippet's body is built by the inline path, so the module calls no `html` and
//    imports none.
//
// The assertions below are the two halves plus the control: a component with no snippet does not
// carry the import either.

import { describe, it, expect } from 'vitest';
import { compile } from '../src/plugin';

const SLOTTED = `<template>
  <pdx-select label="Team member" :options="people" labelField="name" valueField="id">
    @snippet item(option) {
      <span class="who">{{ option.label }}</span>
    }
  </pdx-select>
</template>

<script>
const people = [{ id: 1, name: 'Ada' }];
</script>`;

const PLAIN = `<template><p :title="t">{{ t }}</p></template>
<script>
@prop t: string = '';
</script>`;

const emitted = (source: string): string =>
    compile(source, 'list.pdx', [], undefined, { production: true }).code;

/** The names the module imports from `@pdxui/core`. */
function importedNames(code: string): string[] {
    const m = /import\s*\{([^}]*)\}\s*from\s*'@pdxui\/core'/.exec(code);
    return m ? m[1].split(',').map(s => s.trim()).filter(Boolean) : [];
}

describe('a snippet in a component\'s tag survives the inline path', () => {
    it('it is assigned to the component, as its `item` property', () => {
        expect(emitted(SLOTTED), 'the snippet was dropped from the render').toMatch(/\['item'\]=\(option\)=>\{/);
    });

    it('its body is there too, not just the assignment', () => {
        // An assignment of an empty function renders nothing, and would satisfy the assertion above.
        expect(emitted(SLOTTED), 'the snippet has no body').toContain('who');
    });
});

describe('the module imports what it calls', () => {
    it('a snippet body is built inline, so the module neither calls nor imports html (#364)', () => {
        const code = emitted(SLOTTED);
        expect(code, 'the snippet uses html``').not.toMatch(/html`/);
        expect(importedNames(code), 'an unused html import').not.toContain('html');
        // Its body uses what the inline path imports for it: the text binding.
        expect(importedNames(code)).toContain('bindInterpolation');
    });

    it('and a component with no snippet does not import html either', () => {
        const code = emitted(PLAIN);
        expect(code).not.toMatch(/html`/);
        expect(importedNames(code), 'an unused html import came back').not.toContain('html');
    });
});

describe('and the emitted module parses', () => {
    it('with a snippet in it', () => {
        // `new Function` is a parser that is already here. The import lines are stripped because an
        // import statement is illegal in a function body; the body is never called, only compiled.
        const body = emitted(SLOTTED).replace(/^\s*import\b.*$/gm, '');
        expect(() => new Function(body)).not.toThrow();
    });
});
